criteria.query:
let hb = Heartbeat | where TimeGenerated > ago(2d) | extend Arrived = ingestion_time() | project Computer, TimeGenerated, Arrived;
let gaps = hb | order by Computer asc, TimeGenerated asc | extend Prev = prev(TimeGenerated), PrevC = prev(Computer)
  | where Computer == PrevC and datetime_diff('minute', TimeGenerated, Prev) > 20 and Arrived between (ago(30m) .. ago(15m))
  | project Computer, GapStart = Prev, GapEnd = TimeGenerated, GapMin = datetime_diff('minute', TimeGenerated, Prev);
let power = Event | where TimeGenerated > ago(2d) and EventLog == 'System'
  | where (Source == 'Microsoft-Windows-Kernel-Power' and EventID in (42, 506, 109)) or (Source == 'User32' and EventID == 1074) or (Source == 'EventLog' and EventID == 6006)
  | project Computer, PowerAt = TimeGenerated;
let unexplained = gaps | join kind=leftouter power on Computer
  | extend Hit = iff(isnotnull(PowerAt) and PowerAt between ((GapStart - 10m) .. (GapStart + 15m)), 1, 0)
  | summarize PowerEvents = sum(Hit) by Computer, GapStart, GapEnd, GapMin | where PowerEvents == 0
  | project Computer, Kind = 'silent without a sleep, hibernate or shutdown', Minutes = GapMin, From = GapStart, To = GapEnd;
let stalled = hb | where Arrived between (ago(30m) .. ago(15m)) and datetime_diff('minute', Arrived, TimeGenerated) > 60
  | summarize Late = count(), From = min(TimeGenerated), To = max(TimeGenerated), Minutes = max(datetime_diff('minute', Arrived, TimeGenerated)) by Computer | where Late >= 10
  | project Computer, Kind = strcat('upload stalled while awake (', Late, ' heartbeats over an hour late)'), Minutes, From, To;
union unexplained, stalled
| extend Problem = strcat(Computer, ': ', Kind, ', ', Minutes, ' minutes (', format_datetime(datetime_utc_to_local(From, 'America/Los_Angeles'), 'MM-dd HH:mm'), ' to ', format_datetime(datetime_utc_to_local(To, 'America/Los_Angeles'), 'MM-dd HH:mm'), ' local). Investigate: agent stopped, network blocked, or tampering.')
